INSERT INTO "public"."flower_entries" ("id", "created_at", "entry_date", "content_items", "flower_color", "title", "height", "recipient_pin", "is_compliment") VALUES ('1c25b1ce-7e47-489e-aba1-5b1dd432662e', '2025-11-26 19:33:48.861096+00', '2025-11-26', '[{"type":"text","order":0,"content":"We had some ginger shots and played padel.\\n\\nA pretty Sanaflower won 🙌\\n\\nThe conversations were good\\n\\nWe will kiss soon\\n\\n"},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.473195294991949.jpg","type":"image","order":1},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.324064393277103.jpg","type":"image","order":2},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.8437300902589155.jpg","type":"image","order":3}]', '#facc15', 'Paddle Day 2', '329.19113303552786', null, 'false'), ('1f20eaa3-6968-4587-bce4-37f320d96e28', '2025-12-14 16:53:18.132426+00', '2025-12-14', '[{"type":"text","order":0,"content":"Yesterday was so lovely.\\n\\nAnd although his face might not show it, I know we both had a really good time together. "},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.46798259513261264.jpeg","type":"image","order":1},{"type":"text","order":2,"content":"He picked me up and we went for wings at Romomamas.\\n\\nIt made me laugh because it took me straight back to his Bumble profile where he said “I promise I won’t judge you if we eat wings.” About two months later, we were eating wings together, and he was right… I don’t feel judged by him at all, wings or otherwise. "},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.0393532015141379.jpeg","type":"image","order":3},{"type":"text","order":4,"content":"After that we watched Wicked: For Good. I cried at the end.\\n\\nNot to sound too cringe, but it makes me hope we might leave that kind of mark on each other too… changing each other “for good.” "},{"type":"text","order":5,"content":"(Also, I cant wait to kiss him again)"}]', '#eab308', 'Movie Date ', '240.47766008900226', null, 'false'), ('3459fbad-89ef-48cf-8ed3-b6ef10ec6af1', '2025-12-04 19:22:56.477239+00', '2025-12-04', '[{"type":"text","order":0,"content":"You''re absolutely wonderful! 🌸"}]', '#e17055', '💐 A Compliment for You', '112.81029042901768', '1809', 'true'), ('3ac73925-bd4d-454c-814d-9464d268b334', '2025-12-11 21:37:41.598116+00', '2025-12-11', '[{"type":"text","order":0,"content":"She was dressed, to perfection, all black, with white socks and shoes, and a necklace of a golden cross that danced at her neck with every move. \\nThe padel game was just an excuse to watch her."},{"type":"text","order":1,"content":"We ate at Mozamibik. (The paper towel dispenser was cool)\\n\\nHad a platter for 2—even gave mussels another taste together.  \\n\\nHad a Coke Zero because she knows its my thing and I appreciate that, I will get her to switch over some day. \\n\\n"},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.7148937016915929.jpg","type":"image","order":2},{"type":"text","order":3,"content":"After eating we sat in the car. \\n\\nThoughts screaming to kiss. And then, we did. The kiss was a surprise and it was perfect. \\n\\nThat kiss wasn''t a period, but a comma. A breathless pause representing everything that is yet to come for us. \\n\\n(I could spend the whole day kissing her)"}]', '#fde047', '', '152.98596619019688', null, 'false'), ('6773f84c-50d1-4092-a23c-3825424f7f30', '2025-12-07 20:06:06.181794+00', '2025-12-07', '[{"type":"text","order":0,"content":"He picked me up with flowers today. A true gentleman. <3 "},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.01245672456093494.jpeg","type":"image","order":1},{"type":"text","order":2,"content":"We went to the beach, had sushi, grabbed matcha, and found ourselves back at the beach again. "},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.5898694401287083.jpeg","type":"image","order":3},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.5016326772343316.jpeg","type":"image","order":4},{"type":"text","order":5,"content":"We saw these cute little ducklings. I can’t wait for us to have our own on our farm one day🥺"},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.4977659168612304.jpeg","type":"image","order":6},{"type":"text","order":7,"content":"Today felt light but meaningful, like we’re quietly forming something. \\n\\nAnd the whole time I kept wondering “when is he going to kiss me!??” 😩"}]', '#facc15', 'Sundays for lovers pt.2 ', '271.74307475992583', null, 'false'), ('6d409217-4640-472e-8d54-45dea0eb38d0', '2025-12-04 19:13:14.884455+00', '2025-12-04', '[{"type":"text","order":0,"content":"You''re a wonderful person and I''m grateful for you! 🌺"}]', '#6bcf7f', '💐 A Compliment for You', '82.29263963569772', '0203', 'true'), ('c02d5975-d7ec-4210-b0f1-998087335c17', '2025-11-30 20:39:18.33774+00', '2025-11-30', '[{"type":"text","order":0,"content":"Hey beautiful"},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.9240630219935237.jpeg","type":"image","order":1},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.6771777743839275.jpeg","type":"image","order":2},{"url":"https://cufxlfwtgubcngexkuwc.supabase.co/storage/v1/object/public/flower-images/0.8308243412105872.jpeg","type":"image","order":3},{"type":"text","order":4,"content":"Lunch together, a walk along the beach, and dessert. \\n\\nWe are getting closer and a lot more comfortable with each other (we held hands) \\n\\nHe makes me smile\\n\\nOh, and we saw some beautiful fish swimming around in a pond. Earth and Water. Virgo and Pisces. A quiet reflection of us :)"}]', '#eab308', 'Sundays are for lovers', '250.53648206126482', null, 'false'), ('e35ae658-ab7a-448c-b674-74d233ebf9fe', '2025-12-06 05:40:24.467819+00', '2025-12-06', '[{"type":"text","order":0,"content":"You inspire me!"}]', '#a55eea', 'You inspire me!', '107.05315442692385', '0203', 'true');